import { readFileSync } from "node:fs";
import tokenPolicy, { directThemeAliases } from "./scripts/stylelint-token-policy.mjs";

function declarations(path) {
  return [...readFileSync(path, "utf8").matchAll(/(?:^|[^\w-])(--[a-z0-9-]+)\s*:\s*([^;}{]+)/g)]
    .map((match) => [match[1], match[2].trim()]);
}

// Generated by scripts/build-tokens.ts (pnpm tokens); docs/DESIGN_SYSTEM.md.
const tokens = [...new Set(declarations("src/generated/tokens.css").map(([property]) => property))];
const authored = declarations("src/index.css").filter(([property]) => !tokens.includes(property));
const authoredProperties = directThemeAliases(authored, new Set(tokens));

export default {
  plugins: [tokenPolicy],
  // The generated theme is owned by the token projection; this config lints authored styles.
  ignoreFiles: ["src/generated/**"],
  rules: {
    "color-no-hex": true,
    // Pages style through classes and data hooks; ID selectors out-specify primitives.
    "selector-max-id": 0,
    "ppap/token-policy": {
      tokens,
      aliases: authoredProperties.aliases,
      structural: authoredProperties.structural,
      runtime: [],
    },
  },
};
